window.XP_DATA = {"title":"What Really Happens When You Click Run","titleZh":"点下 Run 的那一瞬间，到底发生了什么？","duration":349.902,"poster":{"t":18.699,"runspot":"[data-seq=\"A\"] .ot-page .pill"},"chapters":[{"t":0.0,"en":"One click, slowed down","zh":"一次点击，放慢来看","act":"A"},{"t":29.545,"en":"The preprocessor","zh":"预处理器","act":"A"},{"t":47.434,"en":"Lexer: tokens","zh":"词法分析：token","act":"B"},{"t":62.289,"en":"Parser: the syntax tree","zh":"语法分析与语义检查","act":"B"},{"t":81.218,"en":"IR","zh":"中间表示 IR","act":"B"},{"t":96.433,"en":"Optimizer: printf becomes puts","zh":"优化器：printf 变成 puts","act":"C"},{"t":117.687,"en":"Back end: x86-64 assembly","zh":"后端：x86-64 汇编","act":"C"},{"t":136.842,"en":"Assembler: machine code with holes","zh":"汇编器：带空洞的机器码","act":"D"},{"t":154.911,"en":"Linker: an executable","zh":"链接器：可执行文件","act":"D"},{"t":178.727,"en":"The shell and fork","zh":"shell 与 fork","act":"E"},{"t":200.395,"en":"The scheduler","zh":"调度器","act":"E"},{"t":215.071,"en":"exec and the address space","zh":"exec 与地址空间","act":"E"},{"t":248.307,"en":"Page fault","zh":"缺页异常","act":"F"},{"t":273.014,"en":"From _start to the CPU","zh":"从 _start 到 CPU","act":"F"},{"t":289.341,"en":"puts, syscall, pixels","zh":"puts、系统调用与像素","act":"F"},{"t":314.789,"en":"Exit, and the whole relay","zh":"进程退出与全程回顾","act":"G"}],"acts":{"A":{"en":"Surface","zh-Hans":"表层"},"B":{"en":"Compile","zh-Hans":"编译"},"C":{"en":"Optimize","zh-Hans":"优化"},"D":{"en":"Link","zh-Hans":"链接"},"E":{"en":"Load","zh-Hans":"加载"},"F":{"en":"Run","zh-Hans":"运行"},"G":{"en":"Return","zh-Hans":"返回"}},"captionsZh":[{"t0":1.026,"t1":2.665,"text":"五行 C 代码"},{"t0":3.162,"t1":5.081,"text":"点一下，Hello, world"},{"t0":5.121,"t1":6.404,"text":"看起来只是一瞬间"},{"t0":6.444,"t1":11.652,"text":"但就在这一眨眼间\n你的代码穿过了一整串程序，进入内核"},{"t0":11.692,"t1":14.589,"text":"在硅片上运行，最后化作了光"},{"t0":15.431,"t1":16.649,"text":"我们把它放慢来看"},{"t0":19.819,"t1":22.168,"text":"这个 Run 按钮其实是两条命令"},{"t0":22.208,"t1":23.96,"text":"先构建，再运行"},{"t0":24.0,"t1":26.776,"text":"而“构建”是一条流水线，分四道工序"},{"t0":26.816,"t1":28.439,"text":"全都藏在一个名字后面"},{"t0":29.965,"t1":32.058,"text":"第一站：预处理器"},{"t0":32.098,"t1":35.13,"text":"它根本不懂 C，只会编辑文本"},{"t0":35.17,"t1":36.624,"text":"#include 的意思是"},{"t0":36.664,"t1":38.622,"text":"把那个文件整个粘贴到这里"},{"t0":39.298,"t1":41.593,"text":"五行代码一下子膨胀成几百行"},{"t0":41.633,"t1":43.598,"text":"里面埋着我们要找的那一行"},{"t0":43.638,"t1":45.685,"text":"printf 的声明"},{"t0":48.354,"t1":49.764,"text":"编译器开始读代码"},{"t0":49.804,"t1":52.068,"text":"词法分析器把字符切分成 token"},{"t0":52.108,"t1":55.39,"text":"关键字、标识符、标点符号"},{"t0":55.694,"t1":57.546,"text":"还有一个字符串字面量"},{"t0":58.042,"t1":59.111,"text":"盯住它"},{"t0":59.151,"t1":61.24,"text":"我们会一路跟着它，直到屏幕上"},{"t0":62.709,"t1":66.295,"text":"语法分析器按照 C 的语法规则\n把这些 token 搭成一棵树（AST）"},{"t0":66.335,"t1":68.038,"text":"一个函数：main"},{"t0":68.085,"t1":70.575,"text":"里面有一次调用和一次返回"},{"t0":70.87,"t1":74.173,"text":"接着，语义分析检查这一切是否说得通"},{"t0":74.498,"t1":75.866,"text":"printf 存在吗？"},{"t0":75.906,"t1":77.78,"text":"在，就是刚贴进来的那段声明"},{"t0":77.984,"t1":79.266,"text":"它接受字符串吗？"},{"t0":79.306,"t1":80.269,"text":"接受"},{"t0":81.638,"t1":84.67,"text":"现在，这棵树被降级为中间表示（IR）"},{"t0":84.71,"t1":89.527,"text":"一种简单、类似汇编的语言\n不属于任何一种特定的 CPU"},{"t0":90.031,"t1":92.295,"text":"我们的字符串是一个 15 字节的数组"},{"t0":92.335,"t1":95.484,"text":"14 个字符，再加一个标记结尾的 0"},{"t0":96.953,"t1":100.411,"text":"然后，优化器一遍又一遍地改写程序"},{"t0":100.451,"t1":102.943,"text":"让它更快，但行为保持不变"},{"t0":103.141,"t1":105.533,"text":"它发现字符串里没有要格式化的内容"},{"t0":105.573,"t1":107.635,"text":"用 printf 就是大材小用"},{"t0":107.745,"t1":111.033,"text":"于是换成更简单的 puts，并去掉换行符"},{"t0":111.073,"t1":112.861,"text":"因为 puts 会自己补上一个"},{"t0":113.565,"t1":114.848,"text":"你从没写过 puts"},{"t0":114.888,"t1":116.538,"text":"是编译器替你做的决定"},{"t0":118.107,"t1":122.077,"text":"后端把这一切翻译成\n针对某一种特定 CPU 的汇编"},{"t0":122.117,"t1":124.74,"text":"这里是 x86-64"},{"t0":124.954,"t1":128.242,"text":"字符串的地址被放进一个叫 rdi 的寄存器"},{"t0":128.282,"t1":130.774,"text":"按照约定，函数从这里取第一个参数"},{"t0":131.014,"t1":132.247,"text":"调用 puts"},{"t0":132.467,"t1":134.347,"text":"把 0 放进 eax"},{"t0":134.387,"t1":135.993,"text":"这就是返回值"},{"t0":137.362,"t1":140.948,"text":"汇编器把每条指令编码成原始的机器码"},{"t0":140.988,"t1":143.267,"text":"main 只有 17 个字节"},{"t0":143.735,"t1":145.352,"text":"但其中有几个是空的"},{"t0":145.656,"t1":147.152,"text":"字符串会放在哪儿？"},{"t0":147.192,"t1":148.419,"text":"puts 在哪儿？"},{"t0":148.63,"t1":152.302,"text":"还没人知道，所以汇编器留下空洞\n每个洞附一张便条（重定位项）"},{"t0":152.342,"t1":153.921,"text":"“以后再来填这里”"},{"t0":155.331,"t1":157.439,"text":"链接器来逐一处理这些便条"},{"t0":157.807,"t1":159.986,"text":"它加入我们从没写过的启动代码"},{"t0":160.026,"t1":161.65,"text":"给所有东西分配最终地址"},{"t0":161.69,"t1":163.027,"text":"再把空洞填上"},{"t0":163.067,"t1":165.374,"text":"但 puts 住在 C 标准库里"},{"t0":165.414,"t1":166.782,"text":"由所有程序共享"},{"t0":166.822,"t1":169.171,"text":"所以这次调用先经过一个小跳板（PLT）"},{"t0":169.211,"t1":170.85,"text":"等程序启动时再接通"},{"t0":171.29,"t1":173.355,"text":"结果就是一个可执行文件"},{"t0":173.595,"t1":175.511,"text":"大约 16 KB"},{"t0":176.087,"t1":177.778,"text":"但它仍然只是一个文件"},{"t0":181.047,"t1":184.207,"text":"第二条命令 ./hello 交给了 shell"},{"t0":184.247,"t1":187.357,"text":"它自己也只是个程序，正等着你输入"},{"t0":187.719,"t1":189.94,"text":"但 shell 自己没法启动程序"},{"t0":189.98,"t1":191.619,"text":"只有内核能做到"},{"t0":191.859,"t1":192.922,"text":"于是它去求内核"},{"t0":193.991,"t1":195.529,"text":"第一步：fork"},{"t0":195.569,"t1":198.303,"text":"内核把 shell 克隆成一个全新的进程"},{"t0":198.343,"t1":199.646,"text":"有自己的进程 ID"},{"t0":200.815,"t1":203.413,"text":"这个新进程只是几百个进程之一"},{"t0":203.632,"t1":207.731,"text":"调度器决定每个 CPU 核心上\n运行哪个进程、运行多久"},{"t0":207.771,"t1":210.945,"text":"时间片只有几毫秒，不停地切换"},{"t0":211.471,"t1":214.322,"text":"轮到这个克隆进程时，它提出了请求"},{"t0":215.491,"t1":218.303,"text":"exec：用这个文件把我替换掉"},{"t0":218.721,"t1":220.516,"text":"内核清空克隆进程的内存"},{"t0":220.556,"t1":222.223,"text":"检查文件的魔数"},{"t0":222.263,"t1":223.759,"text":"再读出里面的“地图”"},{"t0":223.799,"t1":226.2,"text":"什么放到哪儿，从哪儿开始执行"},{"t0":227.469,"t1":229.605,"text":"它搭起一个全新的地址空间"},{"t0":229.645,"t1":232.478,"text":"代码：只读、可执行"},{"t0":232.804,"t1":235.707,"text":"我们的字符串：只读，就在代码旁边"},{"t0":235.747,"t1":238.899,"text":"最上面是栈，存放着程序的参数"},{"t0":239.231,"t1":241.367,"text":"又因为这个文件依赖 libc"},{"t0":241.407,"t1":242.946,"text":"动态链接器会先运行"},{"t0":242.986,"t1":247.158,"text":"把库映射进来\n再把那个跳板接到真正的 puts 上"},{"t0":249.027,"t1":250.565,"text":"直到这时，代码才开始运行"},{"t0":250.605,"t1":252.841,"text":"——或者说，试着运行"},{"t0":253.181,"t1":255.275,"text":"因为它其实还根本不在内存里"},{"t0":255.315,"t1":257.124,"text":"内核只是“答应”了而已"},{"t0":257.379,"t1":260.624,"text":"所以 CPU 迈出的第一步就踩空了"},{"t0":260.664,"t1":261.891,"text":"缺页异常（page fault）"},{"t0":262.775,"t1":265.124,"text":"内核接住了坠落，找到那一页"},{"t0":265.164,"t1":266.66,"text":"在页缓存里，或在磁盘上"},{"t0":266.7,"t1":269.534,"text":"把它映射进来，让 CPU 再试一次"},{"t0":269.931,"t1":271.964,"text":"这一次，地板就在脚下"},{"t0":273.434,"t1":277.106,"text":"程序不是从 main 开始执行，而是从 _start"},{"t0":277.146,"t1":279.367,"text":"这段启动代码先把 C 库准备好"},{"t0":279.407,"t1":280.768,"text":"然后调用 main"},{"t0":281.044,"t1":283.65,"text":"CPU 取指、译码、执行"},{"t0":283.69,"t1":285.563,"text":"每秒几十亿次"},{"t0":285.782,"t1":287.278,"text":"加载字符串的地址"},{"t0":287.318,"t1":288.292,"text":"调用 puts"},{"t0":289.761,"t1":291.769,"text":"puts 把字符串复制到缓冲区"},{"t0":291.809,"t1":294.941,"text":"再补回被编译器拿掉的换行符"},{"t0":295.323,"t1":298.029,"text":"但任何程序都不能直接碰屏幕"},{"t0":298.354,"t1":300.703,"text":"所以它执行一条特殊的指令"},{"t0":300.743,"t1":301.822,"text":"syscall（系统调用）"},{"t0":302.486,"t1":304.664,"text":"CPU 切换到内核态"},{"t0":304.704,"t1":307.352,"text":"内核把 14 个字节写到标准输出"},{"t0":307.392,"t1":309.827,"text":"经过伪终端，送到你的终端程序"},{"t0":309.867,"t1":311.747,"text":"它从字体里找出每个字符的字形"},{"t0":311.787,"t1":313.64,"text":"再把它们画成像素"},{"t0":315.909,"t1":317.49,"text":"main 返回 0"},{"t0":317.53,"t1":321.131,"text":"进程退出，内核回收它的内存"},{"t0":321.471,"t1":324.546,"text":"一直等在那里的 shell 收下退出码"},{"t0":324.586,"t1":325.954,"text":"0，表示成功"},{"t0":325.994,"t1":327.658,"text":"然后打印出新的提示符"},{"t0":329.484,"t1":330.767,"text":"预处理器"},{"t0":330.807,"t1":331.705,"text":"编译器"},{"t0":331.745,"t1":332.644,"text":"优化器"},{"t0":332.684,"t1":333.54,"text":"汇编器"},{"t0":333.58,"t1":334.393,"text":"链接器"},{"t0":334.433,"t1":335.247,"text":"shell"},{"t0":335.287,"t1":336.015,"text":"内核"},{"t0":336.055,"t1":336.783,"text":"加载器"},{"t0":336.823,"t1":337.721,"text":"调度器"},{"t0":337.761,"t1":338.788,"text":"CPU"},{"t0":338.828,"t1":339.869,"text":"终端"},{"t0":340.481,"t1":342.831,"text":"每次你点下 Run，这一切都会发生"},{"t0":342.871,"t1":344.202,"text":"只为了说一声 hello"}],"explore":{"zones":[]},"audio":{"m4a":"audio/film.m4a","duration":350.0},"build":{"at":"2026-10-10 19:29:56","project":"click-run","chaptersFrom":"script/publish.json","zhFrom":"script/subtitles.zh-Hans.json"}};
